/** The countries that have no drawing: `PlayerName` shows their code of two letters. */
export const codeOnlyCountries: readonly string[] = [
  'AD AF AS AW BM BN BT BY BZ DM DO FJ FK GD GI GS GU HT IM IN',
  'IO JE KG KH KI KY KZ LI LK MP MS MT MW NF NI OM PF PN SM SX',
  'SZ TC TM UG UZ VA VE VG VI ZM ZW',
].flatMap((line) => line.split(' '))

const addresses = new Map<string, string>()
const codeOnly = new Set(codeOnlyCountries)

/** The Dutch name of a country, or undefined for a code that is not one of `countryCodes`. */
export function countryName(country: string): string | undefined {
  const code = country.toUpperCase()

  return Object.hasOwn(countryNames, code) ? countryNames[code] : undefined
}

/**
 * The address of the flag of a country as an image: the drawing in a `data:` address, so it
 * costs no request. Undefined when the country has no drawing: it is a country that shows its
 * code (`isCodeOnly`), or not a country of `countryCodes` at all.
 */
export function flagAddress(country: string): string | undefined {
  const code = country.toUpperCase()
  const drawing = Object.hasOwn(flagDrawings, code)
    ? flagDrawings[code]
    : Object.hasOwn(simplifiedFlags, code)
      ? simplifiedFlags[code]
      : undefined

  if (drawing === undefined) {
    return undefined
  }

  let address = addresses.get(code)

  if (address === undefined) {
    address = `data:image/svg+xml,${escapeDrawing(drawing)}`
    addresses.set(code, address)
  }

  return address
}

/** Whether the country has no drawing and shows its code of two letters instead. */
export function isCodeOnly(country: string): boolean {
  return codeOnly.has(country.toUpperCase())
}

/**
 * Writes the drawing so it can stand in a `data:` address: `%`, the quotes, `#`, `<` and `>`
 * are escaped. That is shorter than `encodeURIComponent`, which would escape every space and
 * slash, and the page carries one address for each flag it shows.
 */
function escapeDrawing(drawing: string): string {
  return drawing
    .replaceAll('%', '%25')
    .replaceAll('"', '%22')
    .replaceAll('#', '%23')
    .replaceAll('<', '%3C')
    .replaceAll('>', '%3E')
}
